changeSet.sql:
ALTER TABLE topic_rating
    ADD COLUMN review_text   VARCHAR(200)  NULL COMMENT '评价文字，最多 200 字' AFTER score,
    ADD COLUMN review_images VARCHAR(1024) NULL COMMENT '站内图片 URL，逗号分隔，最多 3 张' AFTER review_text;

rollback.sql:
ALTER TABLE topic_rating
    DROP COLUMN review_images,
    DROP COLUMN review_text;
